// DeepAgentSDKAPIService 是浏览器/前端入口。
//
// HTTP 层负责登录态解析，把 uid 传给进程内 Session 服务；
// 这里的 IDL 故意不出现 uid，避免前端伪造用户身份。
type DeepAgentSDKAPIService interface {
	// 创建一个 agent session，用于空白会话或预创建会话目录项。
	CreateSession(ctx context.Context, req *CreateSessionHTTPRequest) (r *CreateSessionHTTPResponse, err error)
	// 获取左侧栏 session 列表。
	ListSessions(ctx context.Context, req *ListSessionsHTTPRequest) (r *ListSessionsHTTPResponse, err error)
	// 获取左侧栏 project 列表。project 是 session 的工作目录聚合视图，不是独立实体。
	ListProjects(ctx context.Context, req *ListProjectsHTTPRequest) (r *ListProjectsHTTPResponse, err error)
	// 获取 session 详情首屏数据，包括 session 和 threads。
	GetSession(ctx context.Context, req *GetSessionHTTPRequest) (r *GetSessionHTTPResponse, err error)
	// 更新 session 标题、归档状态等目录属性。
	UpdateSession(ctx context.Context, req *UpdateSessionHTTPRequest) (r *UpdateSessionHTTPResponse, err error)
	// 关闭或归档一个 session。
	CloseSession(ctx context.Context, req *CloseSessionHTTPRequest) (r *CloseSessionHTTPResponse, err error)
	// 从侧边栏移除一个 project：关闭该 project 下 active sessions，并保留
	// workspace、timeline、history、checkpoint 和 memory。
	CloseProject(ctx context.Context, req *CloseProjectHTTPRequest) (r *CloseProjectHTTPResponse, err error)
	// 给 session 提交用户输入或控制指令；普通输入没有 main thread 时由后端按需创建。
	SubmitInput(ctx context.Context, req *SubmitInputHTTPRequest) (r *SubmitInputHTTPResponse, err error)
	// 停止 session 当前正在执行的 turn。
	StopRunning(ctx context.Context, req *StopRunningHTTPRequest) (r *StopRunningHTTPResponse, err error)
	// 查询 session timeline 历史事件，用于刷新恢复。
	//
	// deep_agent_sdk 直接请求 Agent Coordinator ListEvents/ListTurnEvents，并把 AC Event.Payload
	// 作为 DeepAgent demo 自有 JSON event 协议透传给前端；不经过 deep_agent_sdk_session RPC。
	ListTimeline(ctx context.Context, req *ListTimelineHTTPRequest) (r *ListTimelineHTTPResponse, err error)
}

